from funcy import memoize, cache, reraise
from funcy.calc import SkipMemoization

for decorate in (memoize, memoize(), lambda f: cache(60)(f)):
    calls = []
    @decorate
    def f(*args, **kwargs):
        calls.append((args, kwargs))
        return len(calls)
    assert f(1, a=2, b=3) == f(1, b=3, a=2) == 1
    assert f(2) == 2
    f.invalidate(1, b=3, a=2)
    f.invalidate(1, a=2, b=3)
    assert f(1, a=2, b=3) == 3
    assert f(2) == 2
    memory = f.memory
    f.invalidate_all()
    assert f.memory is memory and memory == {}
    assert f.skip is SkipMemoization
    assert f() == 4

for decorate in (memoize, lambda f: cache(60)(f)):
    @decorate(key_func=lambda x: x.lower()) if decorate is memoize else cache(60, key_func=lambda x: x.lower())
    def f(x):
        return object()
    a = f('A')
    assert f('a') is a
    f.invalidate('a')
    assert f('A') is not a
    for args in ((), ('uncached',)):
        @decorate
        def skip():
            raise SkipMemoization(*args)
        assert skip() == (args[0] if args else None)
        assert skip.memory == {}
assert cache.skip is memoize.skip is SkipMemoization

original = ValueError('original')
seen = []
def transform(e):
    seen.append(e)
    return RuntimeError(str(e))
for into in (RuntimeError, RuntimeError('fixed'), transform):
    try:
        with reraise(ValueError, into):
            raise original
    except RuntimeError as e:
        assert e.__cause__ is original
        if into is RuntimeError:
            assert e.args == ()
        elif isinstance(into, RuntimeError):
            assert e is into
        else:
            assert str(e) == 'original'
assert seen == [original]

@reraise(ValueError, transform)
def fail():
    raise original
for _ in range(2):
    try:
        fail()
    except RuntimeError as e:
        assert e.__cause__ is original
print('Focused API checks passed')
